// 年の見せ方：数→「1534」・'1522?'→「1522ごろ」・null→「不詳」（en：c. 1522・unknown）
export const yearText = (y, en) => (y == null ? (en ? 'unknown' : '不詳') : typeof y === 'string' ? (en ? `c. ${y.replace('?', '')}` : `${y.replace('?', '')}ごろ`) : String(y));
